  DROP FUNCTION  IF EXISTS getpersontransportationbyid( uuid,  character varying);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 CREATE OR REPLACE FUNCTION getpersontransportationbyid(v_persontransportationid uuid, v_securityusersid character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  RETURNS TABLE(totalcount bigint, persontransportationid uuid, insertedon timestamp without time zone, notes text, pickuptime timestamp without time zone, dropofftime timestamp without time zone, pickuplocation character varying, dropofflocation character varying, appointmentdate timestamp without time zone, workerid bigint, county character varying, status text, dateoftransport timestamp without time zone, chargereason character varying, courttime timestamp without time zone, courtlocation character varying, dob timestamp without time zone, youthname character varying, droptime timestamp without time zone, locationfromtypekey character varying, locationtotype character varying, allegationid uuid, allegationname character varying, requestedby text, requesteddate timestamp without time zone)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 SELECT COUNT(1) OVER() as totalcount,*                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         SELECT DISTINCT PT.persontransportationid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                         PT.insertedon,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                         PT.notes,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                         PT.pickuptime as pickuptime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                         PT.droptime as dropofftime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                         CAST (CASE WHEN PT.otherlocationfrom is null THEN LFT.description ELSE PT.otherlocationfrom  END as character varying)as pickuplocation,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                         CAST (CASE WHEN  PT.otherlocationto is null  THEN LTT.description ELSE PT.otherlocationto END as character varying)as dropofflocation ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                         PT.appointmentdate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                         UP.cjamspid as workerid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                         paa.county,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                         (SELECT rst.typedescription
                                         FROM routing rt 
                                         INNER JOIN routingstatustype rst ON rst.sequencenumber  =rt.routingstatustypeid
                                         AND rst.activeflag =1 
		                                 WHERE rt.activeflag=1  
		                                 AND rt.objectid  = (PT.persontransportationid :: character varying)LIMIT 1 )as status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                         PT.dateoftransport,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                         PT.chargereason,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                         PT.courttime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                         PT.courtlocation,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                         PT.dob,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                         PT.youthname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                         PT.droptime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                         LFT.locationfromtypekey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                         LTT.locationtotypekey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                         PT.allegationid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                             (SELECT alle.name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                          FROM allegation alle                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                          WHERE alle.activeflag =1 AND alle.allegationid = PT.allegationid LIMIT 1) allegationname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                             UP.firstname || ' ' || UP.lastname ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                             PT.insertedon                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
     FROM persontransportation PT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
     INNER JOIN locationfromtype LFT on LFT.locationfromtypekey=PT.locationfromtypekey and LFT.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
     INNER JOIN locationtotype LTT on LTT.locationtotypekey = PT.locationtotypekey and LTT.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
     LEFT JOIN (select pa.county,pa.personid FROM personaddress pa                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
     WHERE personaddresstypekey ='C'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
     AND activeflag =1 LIMIT 1) as PAA  on PAA.personid = PT.personid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
     LEFT JOIN userprofile UP on UP.securityusersid=v_securityusersid and UP.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
     WHERE PT.persontransportationid=v_persontransportationid and PT.activeflag=1)as ast ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       

